DO $$
DECLARE
  v_incoming INTEGER;
  v_source_keys INTEGER;
  v_categories INTEGER;
  v_resolved INTEGER;
BEGIN
  SELECT COUNT(*), COUNT(DISTINCT source_key) INTO v_incoming, v_source_keys FROM question_bank_v2_incoming;
  IF v_incoming <> 2000 OR v_source_keys <> 2000 THEN
    RAISE EXCEPTION 'V2 bank requires exactly 2000 incoming rows and source keys; got % rows and % keys', v_incoming, v_source_keys;
  END IF;
  SELECT COUNT(*) INTO v_categories FROM public.categories WHERE slug IN ('grammar', 'vocabulary', 'reading', 'listening', 'speaking', 'writing');
  IF v_categories <> 6 THEN
    RAISE EXCEPTION 'V2 bank requires all six category slugs; resolved %', v_categories;
  END IF;
  SELECT COUNT(*) INTO v_resolved FROM question_bank_v2_incoming AS i JOIN public.categories AS c ON c.slug = i.category_slug;
  IF v_resolved <> 2000 THEN
    RAISE EXCEPTION 'V2 bank requires exactly 2000 resolved rows; got %', v_resolved;
  END IF;
END $$;

INSERT INTO public.questions (category_id, difficulty, type, stimulus, question, prompt, options, correct_answer, explanation, status, content_metadata, content_hash, batch_id, batch_metadata, source_key)
SELECT c.id, i.difficulty, i.type, i.stimulus, i.question, i.prompt, i.options::jsonb, i.correct_answer, i.explanation, i.status, i.content_metadata::jsonb, i.content_hash, i.batch_id, i.batch_metadata::jsonb, i.source_key
FROM question_bank_v2_incoming AS i
JOIN public.categories AS c ON c.slug = i.category_slug
ON CONFLICT (source_key) WHERE source_key IS NOT NULL DO UPDATE SET
  category_id = EXCLUDED.category_id, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
  stimulus = EXCLUDED.stimulus, question = EXCLUDED.question, prompt = EXCLUDED.prompt,
  options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation,
  status = EXCLUDED.status, content_metadata = EXCLUDED.content_metadata, content_hash = EXCLUDED.content_hash,
  batch_id = EXCLUDED.batch_id, batch_metadata = EXCLUDED.batch_metadata;

DO $$
DECLARE
  v_v2_rows INTEGER;
  v_matched_rows INTEGER;
BEGIN
  SELECT COUNT(*) INTO v_v2_rows FROM public.questions WHERE batch_id = 'english-bank-2000-v2';
  SELECT COUNT(*) INTO v_matched_rows
  FROM public.questions AS q
  JOIN question_bank_v2_incoming AS i ON i.source_key = q.source_key
  WHERE q.batch_id = 'english-bank-2000-v2';
  IF v_v2_rows <> 2000 OR v_matched_rows <> 2000 THEN
    RAISE EXCEPTION 'Refusing to archive V1: expected exactly 2000 V2 rows matched to incoming; got % total and % matched', v_v2_rows, v_matched_rows;
  END IF;
  UPDATE public.questions SET status = 'archived'
  WHERE batch_id = 'english-bank-2000-v1' AND status = 'published';
END $$;

COMMIT;
